content.text:
                f.data = c.rest();
                f.v3 = f.data.length;
            }
            if (f.v2 + f.v3 > MAX62) {
                throw c.err();
            }
            break;
        case 0x10:
        case 0x12:
        case 0x13:
        case 0x14:
        case 0x16:
        case 0x17:
        case 0x19:
            f.v1 = c.vi();
            if ((t == 0x12 || t == 0x13 || t == 0x16 || t == 0x17) && f.v1 > STREAMS_CAP) {
