            }
            break;
        case 0x18:
            f.v1 = c.vi();
            f.v2 = c.vi();
            if (f.v2 > f.v1) {
                throw c.err();
            }
            f.cidLen = c.one();
            if (f.cidLen < 1 || f.cidLen > 20) {
                throw c.err();
            }
            f.cid = c.take(f.cidLen);
            f.token = c.take(16);
            break;
        case 0x1a:
        case 0x1b:
            f.data = c.take(8);
            break;
        case 0x1c:
            f.v1 = c.vi();
            f.v2 = c.vi();
            f.v3 = c.vi();
            f.data = c.take(f.v3);
            break;
        case 0x1d:
            f.v1 = c.vi();
            f.v2 = c.vi();
            f.data = c.take(f.v2);
            break;
        case 0x30:
            f.data = c.rest();
            break;
        case 0x31:
            f.v1 = c.vi();
            f.data = c.take(f.v1);
            break;
        default:
            throw new WireException(FRAME_ENCODING_ERROR, fs);
    }
    f.end = c.p;
    return f;
}
